def can_learn(species_id: int, item_id: int) -> bool:
    """True if the species can learn TM/HM `item_id` (289..346). Unknown species -> True (let the
    game decide rather than refuse wrongly)."""
    mask = LEARNSETS.get(species_id)
    return True if mask is None else bool(mask >> (item_id - 289) & 1)
